import React, { useState } from "react";
import Header from "./components/Header";
import Footer from "./components/Footer";
import Items from "./components/Items";

function App() {
  // Называем переменную items, а не props
  const [items] = useState([
    {
      id: 1,
      title: 'Hoodie',
      img: 'HoodieGray.jpg',
      desc: 'Comfort + Whyte Style.',
      category: 'Zip',
      price: '49.99'
    },
    {
      id: 2,
      title: 'Jacket',
      img: 'jacketWhite.jpg',
      desc: 'Jacket for StreatWear.',
      category: 'Jacket',
      price: '149.00'
    },
    {
      id: 3,
      title: 'Hoodie Baggy',
      img: 'HoodieBlue.jpg',
      desc: 'Fresh and Ice.',
      category: 'Hoodie',
      price: '69.99'
    }
  ]);

 const [orders, setOrders] = useState([]);

  // Создаем функцию добавления (внутри App!)
  const addToOrder = (item) => {
    // Проверяем, есть ли товар уже в корзине
    let isInArray = false;
    orders.forEach(el => {
      if(el.id === item.id) isInArray = true;
    });

    // Если нет, добавляем его в массив orders
    if(!isInArray) {
      setOrders([...orders, item]);
    }
  };


  const deleteOrder = (id) => {
  setOrders(orders.filter(el => el.id !== id));
}


  return (
    <div className="wrapper">
      <Header orders={orders} onDelete={deleteOrder}/>
      {/* Передаем наш массив items */}
      <Items items={items} onAdd={addToOrder}/>
      <Footer />
    </div>
  );
}




export default App;
